#!/usr/bin/env python3
import sys
import re
from bs4 import BeautifulSoup

def remove_javascript(html_content):
    soup = BeautifulSoup(html_content, 'html.parser')

    # Remove all <script> tags
    for script in soup.find_all('script'):
        script.decompose()

    # Remove all event handler attributes (on*)
    for tag in soup.find_all(True):
        attrs = list(tag.attrs)
        for attr in attrs:
            if attr.lower().startswith('on'):
                del tag[attr]

    # Replace javascript: in href, src, action, etc.
    js_pattern = re.compile(r'^javascript:', re.IGNORECASE)
    for tag in soup.find_all(True):
        for attr in ['href', 'src', 'action', 'formaction', 'background', 'cite', 'data', 'poster', 'profile']:
            if tag.has_attr(attr):
                val = tag[attr]
                if isinstance(val, list):
                    # sometimes attribute can have multiple values, ignore
                    continue
                if js_pattern.match(val):
                    tag[attr] = '#'

    # Also handle data: URIs that contain javascript? Not required.

    # Return as string
    return str(soup)

if __name__ == '__main__':
    if len(sys.argv) != 2:
        print('Usage: python3 filter.py <html_file>')
        sys.exit(1)
    filename = sys.argv[1]
    try:
        with open(filename, 'r', encoding='utf-8') as f:
            content = f.read()
    except Exception as e:
        print(f'Error reading file: {e}')
        sys.exit(1)

    new_content = remove_javascript(content)

    try:
        with open(filename, 'w', encoding='utf-8') as f:
            f.write(new_content)
    except Exception as e:
        print(f'Error writing file: {e}')
        sys.exit(1)

    print(f'Removed JavaScript from {filename}')
EOF
